    const exhibits = getMuseumExhibits();
    const exhibit = getMuseumExhibit(state.museum3d?.exhibitId) || exhibits[0];
    if (!exhibit) { els.messages.appendChild(emptyPanel("Create an exhibit to explore the 3D museum.")); return; }
